#!/usr/bin/env python3
"""Generates rtl/trig_lut.v: a 256-entry cosine ROM in Q1.14 fixed point.

Angle 0..255 maps to 0..2*pi. sin(a) is read from the same table as cos(a - 64),
so one table serves both. The ROM is a pure combinational case statement, so it
synthesizes into LUTs and needs no .mem file in the Vivado project.
"""
import math
import pathlib

out = pathlib.Path(__file__).resolve().parent.parent / "rtl" / "trig_lut.v"

lines = [
    "// AUTO-GENERATED by scripts/gen_trig_lut.py -- do not edit by hand.",
    "// cos/sin of an 8-bit angle (256 steps per turn), signed Q1.14 (16384 = 1.0).",
    "module trig_lut (",
    "    input  wire [7:0]         angle,",
    "    output wire signed [15:0] cos_q14,",
    "    output wire signed [15:0] sin_q14",
    ");",
    "    function signed [15:0] cos_rom;",
    "        input [7:0] a;",
    "        begin",
    "            case (a)",
]
for a in range(256):
    v = int(round(math.cos(2 * math.pi * a / 256) * 16384))
    v = max(-16384, min(16384, v))
    lines.append(f"                8'd{a:<3}: cos_rom = {'-' if v < 0 else ''}16'sd{abs(v)};")
lines += [
    "                default: cos_rom = 16'sd0;",
    "            endcase",
    "        end",
    "    endfunction",
    "",
    "    assign cos_q14 = cos_rom(angle);",
    "    assign sin_q14 = cos_rom(angle - 8'd64);",
    "endmodule",
    "",
]
out.write_text("\n".join(lines))
print(f"wrote {out}")
